func sumArray(_ nums: [Int], _ index: Int = 0) -> Int {
    guard index < nums.count else { return 0 }
    return nums[index] + sumArray(nums, index + 1)
}
print(sumArray([1, 2, 3, 4, 5]))

func fib(_ n: Int) -> Int {
    if n <= 1 { return n }
    return fib(n - 1) + fib(n - 2)
}
print(fib(6))

func reverseStr(_ s: String) -> String {
    guard let first = s.first else { return "" }
    return reverseStr(String(s.dropFirst())) + String(first)
}
print(reverseStr("swift"))

final class TreeNode {
    var val: Int
    var left: TreeNode?
    var right: TreeNode?
    init(_ val: Int, _ left: TreeNode? = nil, _ right: TreeNode? = nil) {
        self.val = val; self.left = left; self.right = right
    }
}
func countNodes(_ root: TreeNode?) -> Int {
    guard let node = root else { return 0 }
    return 1 + countNodes(node.left) + countNodes(node.right)
}
let tree = TreeNode(1, TreeNode(2), TreeNode(3, TreeNode(4), nil))
print(countNodes(tree))

func power(_ base: Int, _ exp: Int) -> Int {
    if exp == 0 { return 1 }
    return base * power(base, exp - 1)
}
print(power(2, 5))

func countChar(_ s: Substring, _ target: Character) -> Int {
    guard let first = s.first else { return 0 }
    let match = first == target ? 1 : 0
    return match + countChar(s.dropFirst(), target)
}
print(countChar("banana"[...], "a"))

func gcd(_ a: Int, _ b: Int) -> Int {
    if b == 0 { return a }
    return gcd(b, a % b)
}
print(gcd(48, 18))

func countSubsets(_ n: Int) -> Int {
    if n == 0 { return 1 }
    return 2 * countSubsets(n - 1)
}
print(countSubsets(4))

