func factorial(_ n: Int) -> Int {
    guard n > 1 else {
        return 1
    }
    return n * factorial(n - 1)
}

print(factorial(5))
print(factorial(0))

func fibonacciMemoized(_ n: Int, _ memo: inout [Int: Int]) -> Int {
    if n <= 1 { return n }
    if let cached = memo[n] { return cached }
    let result = fibonacciMemoized(n - 1, &memo) + fibonacciMemoized(n - 2, &memo)
    memo[n] = result
    return result
}

var cache: [Int: Int] = [:]
print(fibonacciMemoized(10, &cache))
print(fibonacciMemoized(20, &cache))

func isPalindromeRecursive(_ s: String) -> Bool {
    let chars = Array(s)
    func check(_ left: Int, _ right: Int) -> Bool {
        if left >= right { return true }
        if chars[left] != chars[right] { return false }
        return check(left + 1, right - 1)
    }
    return check(0, chars.count - 1)
}

print(isPalindromeRecursive("racecar"))
print(isPalindromeRecursive("swift"))
